document.getElementById('start-evaluation').addEventListener('click', function(e) {
    e.preventDefault(); // Prevent default anchor behavior

    frappe.call({
        method: 'press_affairs_app.api.check_journalist_profile_exists',
        callback: function(r) {
            if (r.exc) {
                // If an unexpected error occurred
                alert("An unexpected error occurred.");
                return;
            }
            console.log("r.message.exists",r.message.exists);

            if (!r.message.logged_in) {
                // If the user is not logged in (based on the flag)
                // Show a custom message with a link (using alert, which only shows text)
                const loginMessage = r.message.error + " Click OK to go to the login page.";
                alert(loginMessage);

                // Redirect to login page, with current URL as redirect_to parameter
                const currentUrl = window.location.pathname; // e.g., /platform
                window.location.href = `/login?redirect-to=${encodeURIComponent(currentUrl)}`;
                return;
            }
            console.log("r.message.exists",r.message.exists);

            // If logged in, check if profile exists
            if (r.message.exists) {
                window.location.href = '/press/foreign-jour';               
            } else {
                window.location.href = '/press/my-profile';
                console.log("r.message.exists",r.message.exists);
            }
        }
    });
});


